const workspaceBaseSupportCard=supportCard;supportCard=function(req){const box=workspaceBaseSupportCard(req);for(const p of box.querySelectorAll('p'))if(p.textContent.includes(req.id))p.remove();return box;};

function workspaceAwaitPlan(resume){if(window.crmDurable.getPhase()!=='PENDING')return true;const editor=planEditor,identity=cfgRoleKey();if(window.crmDurable.whenReady)window.crmDurable.whenReady({foreground:true}).then(()=>{if(editor===planEditor&&identity===cfgRoleKey())resume();}).catch(e=>message(errorMessage(e),true));return false;}
